from pathlib import Path
import json
P=Path(__file__).resolve().parent
E=json.loads((P/'extraction.json').read_text())
rows=[
('R053','Empirical evaluator audit','Test effects of model attribution on judgments.','Model identity labels, preference votes and quality ratings.','Three models evaluate blog posts under true, false and absent labels; labels alter ratings and preferences.','Small model/task set; this tests automated judging, not human comprehension.','Methods, results, discussion and conclusion sections.'),
('R054','Empirical evaluation audit','Compare static medical scores with dynamic stress tests.','Robustness, privacy, fairness and hallucinations.','Dynamic adversarial testing of 15 LLMs finds failures not visible in static accuracy; clinician comparisons check the audit procedure.','Adversarial sample is not an estimate of everyday failure rates; clinician agreement is not ground truth by itself.','Methods and results; Discussion section 3; supplementary validation.'),
('R055','Empirical evaluator audit and benchmark','Test multilingual evaluator behavior.','Language consistency, absolute score fairness and preference agreement.','Experiments with 12 evaluator LLMs identify differences across languages and scoring modes.','New meta evaluation dataset also has sampling and reference judgment assumptions. No general novice review study.','Evaluation sections and conclusion section 6.'),
('R071','Empirical metric audit','Test whether text overlap scores conceal loss of clinical content.','Clinical terminology, lexical diversity, semantic erasure and demographic associations.','Compares decoding strategies and introduces CAD/WAE measures; high text similarity can coexist with missing clinical terms.','Radiology task and binary sex analysis; lexical measures do not themselves establish clinical correctness.','Methods; Results and Discussion section 4; Conclusion and Future Work section 5.'),
('R079','Reporting guidance with case applications','Guide reporting of LLM use in health economics research.','Ten reporting domains including accuracy, reproducibility and fairness.','Literature and expert input inform a checklist applied to two studies.','Adjacent evidence: reporting a study is different from reviewing a benchmark; authors call for further empirical testing.','Methods, results, limitations and checklist in the accessible preprint.'),
('R256','Review and data quality framework','Organise medical dataset quality concerns.','15 awareness dimensions in METRIC.','Review identifies 5,408 records and includes 120; proposes dimensions for examining datasets.','Dimensions are explicitly awareness categories; measurement and assessment of appropriateness remain subsequent steps. Not a demonstrated reviewer accessibility benefit.','HTML Methods, Results and Discussion; figure 3.'),
('R294','Empirical fairness measurement study','Assess limitations of binary bias probes.','Disparate treatment, identities, stereotypes and coverage of social groups.','SOFA compares a broader set of identities and prompts with prior bias benchmarks.','Group coverage and prompt assumptions limit interpretation; not a general benchmark review tool.','Sections on methodology, experiments, discussion and limitations; ACL PDF.'),
('R299','Measurement pipeline with experiments','Calibrate bias benchmarking against context and metric bias.','Baseline calibration, counterfactual branching and disparity.','SAGED pipeline applied to G20 country prompts and four model families.','Examples depend on sentiment tools and contexts; calibration does not make a measure value neutral.','Pipeline and experiments; discussion/limitations in PDF.'),
('R325','Empirical robustness method','Test consistency under related instruction prompts.','Nuance oriented reliability and reliable@k.','IFEVAL++ experiments across 20 proprietary and 26 open models show performance changes under prompt variation.','Generated prompt quality and reference constraints limit interpretation; reliability meaning differs from test retest consistency.','Method and evaluation sections; conclusion and limitations.'),
('R327','Measurement framework with experiments','Broaden representation of social groups in bias evaluation.','Group fairness, target attribute combinations and statement generation.','GFAIR taxonomy, benchmark and mitigation experiments.','Selected social groups and tasks do not establish universal fairness; no measured reviewer understanding.','Framework, experiments and limitations; ACL PDF.'),
('R331','Empirical robustness audit','Assess sensitivity to equivalent drug names.','Brand/generic substitution, robustness and contamination.','Physician annotated substitutions on MedQA and MedMCQA expose performance changes.','Limited tasks and model samples; contamination is a possible explanation, not the only established cause.','Dataset construction, experiments and limitations; ACL PDF.'),
('R356','Review and checklist','Guide release readiness decisions for generative AI software.','Performance, monitoring, deployment and user experience.','Grey literature review produces a readiness checklist.','Adjacent comparator: product release readiness is not benchmark quality; checklist availability does not establish usefulness for novices.','Review method, checklist and discussion.'),
('R365','Position and reporting proposal','Make consequential safety claims reproducible.','Claim inventories; public, controlled and restricted disclosure.','Proposes disclosure tiers and review requirements with examples.','Normative recommendations; not an observed effect of a reporting intervention.','Scope and proposed disclosure framework sections.'),
('R377','Workflow and teaching case','Help scientists without programming expertise reproduce and assess published models.','Implementation, validation, applicability and recovery from failed steps.','Three BSc chemistry students and a tutor apply PRAISE as a proof of principle.','Adjacent accessibility evidence, not a comparative benchmark review trial. Small guided case cannot establish general benefit or reduced duration.','Workflow sections 4–5 and proof of principle case study.'),
('C03','Conceptual and mathematical proposal','Model change in benchmark validity over time.','Semantic leakage, novelty, provenance, evaluator coupling and construct drift.','Defines benchmark half life relative to an operational specification; mathematical arguments.','Repository preprint; definitions and assumptions are proposals, not measured universal rates of validity decay.','Definitions, propositions and limitations in the 2026 PDF.')]
for sid,typ,purpose,concepts,ev,limit,loc in rows:
 E.append(dict(source_id=sid,source_type=typ,purpose=purpose,intended_reviewers='Researchers or practitioners in the source domain; R377 explicitly addresses nonprogrammers.',concepts_and_criteria=concepts,answer_format_and_guidance='See source method: workflow, measurements or reporting items; no shared categorical scale assumed.',missing_information='No uniform missing information rule established in these inspected sections. Do not substitute missing reporting for an observed negative result.',accessibility_and_effort='No measured improvement in general benchmark review understanding or effort identified in the inspected sections. See evaluation field for actual human input or use.',evaluation_and_findings=ev,evidence_assessment=limit,evidence_locator=loc,author_review='pending'))
for e in E:
 if e['source_id']=='S05':
  e['accessibility_and_effort']='Definitions and guided rating. Raters were AI related undergraduate/graduate students; time taken in hours was requested (printed p. 104). This records effort collection, but the chapter does not report a comparative novice accessibility or time saving result. Agreement is not correctness.'
  e['evaluation_and_findings']='36 instruments; first two rated by coordinators and all raters, next eleven by four raters, then two per instrument. Discussion led to revisions. Harder facets included Capability, Coverage, Specificity, Adjustability and Ambition.'
(P/'extraction.json').write_text(json.dumps(E,ensure_ascii=False,indent=2)+'\n')
print(len(E))
